"use client";

/**
 * ShortcutMap. The "Keyboard shortcuts" sheet a desktop app opens with ?:
 * the list of what each shortcut does, and above it the keyboard drawn in
 * Kbd caps. Point at a shortcut and its keys light on the board; press keys
 * on your own keyboard and the drawn ones go down with them.
 *
 * The list is the content: each shortcut's keys as Kbd caps and what it
 * does, in words. The board is a picture of it and is hidden from assistive
 * technology.
 */
import { Fragment, useState } from "react";
import { Kbd } from "../kbd";
import { BOARD, lit } from "./board";
import "./shortcut-map.css";

export interface Shortcut {
  /** The keys, in the order they're held: ["Cmd", "K"]. */
  keys: readonly string[];
  /** What it does. */
  label: string;
}

export interface ShortcutMapProps {
  shortcuts: readonly Shortcut[];
  /** The list's accessible name. Default "Keyboard shortcuts". */
  label?: string;
  /** Draw the keyboard over the list. Default true. */
  board?: boolean;
}

export function ShortcutMap({ shortcuts, label = "Keyboard shortcuts", board = true }: ShortcutMapProps) {
  const [pointed, setPointed] = useState<number | null>(null);
  const on = pointed === null ? new Set<string>() : lit(shortcuts[pointed]!.keys);
  return (
    <div className="echo-shortcut-map">
      {board ? (
        <div className="echo-shortcut-map__board" aria-hidden="true">
          {BOARD.map((row, r) => (
            <div key={r} className="echo-shortcut-map__row">
              {row.map((key, i) => (
                <span key={i} className="echo-shortcut-map__slot" data-width={key.width} data-lit={on.has(key.legend) || undefined}>
                  <Kbd>{key.legend}</Kbd>
                </span>
              ))}
            </div>
          ))}
        </div>
      ) : null}
      <ul className="echo-shortcut-map__list" aria-label={label} onPointerLeave={() => setPointed(null)}>
        {shortcuts.map((s, i) => (
          <li key={s.label} className="echo-shortcut-map__item" onPointerEnter={() => setPointed(i)}>
            <span className="echo-shortcut-map__keys">
              {s.keys.map((key, j) => (
                <Fragment key={j}>
                  {j > 0 ? <span className="echo-shortcut-map__then" aria-hidden="true">+</span> : null}
                  <Kbd>{key}</Kbd>
                </Fragment>
              ))}
            </span>
            <span className="echo-shortcut-map__label">{s.label}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

/**
 * ShortcutMap. A keyboard of Kbd caps over the list of shortcuts; a lit key
 * is the primary cap. Composes var(--echo-*) — no hex literals; the only
 * fixed values are the key light.
 */
.echo-shortcut-map {
  container-type: inline-size;
  display: grid;
  gap: var(--echo-space-10);
  max-inline-size: 100%;
  min-inline-size: 0;
}

/* The board scales to fit: 15 units and their gaps across the width it has. */
.echo-shortcut-map__board {
  --sm-unit: clamp(12px, calc((100cqi - 88px) / 15.5), 24px);
  display: grid;
  gap: var(--echo-space-2);
  justify-content: start;
  padding: var(--echo-space-5);
  border-radius: var(--echo-radius-lg);
  box-shadow: var(
    --echo-shadow-well,
    inset 0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent)
  );
  max-inline-size: 100%;
  /* The cap counts the padding too (BUG-128). */
  box-sizing: border-box;
}
.echo-shortcut-map__row {
  display: flex;
  gap: var(--echo-space-2);
}
.echo-shortcut-map__slot {
  display: flex;
  flex: none;
  inline-size: calc(var(--sm-unit) * var(--w, 1));
}
.echo-shortcut-map__slot[data-width="1.25"] { --w: 1.25; }
.echo-shortcut-map__slot[data-width="1.5"] { --w: 1.5; }
.echo-shortcut-map__slot[data-width="1.75"] { --w: 1.75; }
.echo-shortcut-map__slot[data-width="2.25"] { --w: 2.25; }
.echo-shortcut-map__slot[data-width="2.75"] { --w: 2.75; }
.echo-shortcut-map__slot[data-width="5.5"] { --w: 5.5; }
.echo-shortcut-map__slot > .echo-kbd {
  flex: 1;
  min-inline-size: 0;
  overflow: hidden;
  /* A long legend on a small cap is cut, not spilled: the board is only a picture. */
  --echo-clip: decorative;
  padding-inline: var(--echo-space-1);
  font-size: var(--echo-text-3xs);
}
/* Lit: the keys of the shortcut you're pointing at. */
.echo-shortcut-map__slot[data-lit] > .echo-kbd {
  color: var(--echo-primary-cap-ink, var(--echo-text));
  background: linear-gradient(180deg, var(--echo-primary-cap-top) 0%, var(--echo-primary-cap-mid) 45%, var(--echo-primary-cap-base) 100%);
}

.echo-shortcut-map__list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr));
  gap: 0 var(--echo-space-10);
  margin: 0;
  padding: 0;
  list-style: none;
}
.echo-shortcut-map__item {
  display: flex;
  align-items: center;
  gap: var(--echo-space-6);
  padding-block: var(--echo-space-4);
  border-block-end: var(--echo-border-hairline, 1px) solid var(--echo-seam);
  box-shadow: var(--echo-shadow-hairline, 0 1px 0 rgb(255 255 255 / calc(0.04 * var(--echo-gloss, 1))));
}
.echo-shortcut-map__keys {
  display: inline-flex;
  align-items: center;
  gap: var(--echo-space-2);
  flex-shrink: 0;
  white-space: nowrap;
}
.echo-shortcut-map__then {
  font-family: var(--echo-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--echo-text-2xs);
  color: var(--echo-text-dim);
}
.echo-shortcut-map__label {
  font-family: var(--echo-font-sans, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-sm);
  color: var(--echo-text);
  overflow-wrap: anywhere;
}

/* Too narrow for a keyboard (a phone, or very large text): the list stands alone. */
@container (max-width: 26rem) {
  .echo-shortcut-map__board {
    display: none;
  }
}

@media (forced-colors: active) {
  .echo-shortcut-map__slot[data-lit] > .echo-kbd {
    background: Highlight;
    color: HighlightText;
  }
}

/**
 * The keyboard a ShortcutMap draws, and how a shortcut's keys find their
 * caps on it. Pure: no React, no DOM.
 */

/** A cap on the board: its legend, and how many units wide it is. */
export interface BoardKey {
  legend: string;
  /** Width in units; 1 is a letter key. */
  width: number;
}

const k = (legend: string, width = 1): BoardKey => ({ legend, width });

/** A compact US layout, one row per array. */
export const BOARD: readonly (readonly BoardKey[])[] = [
  [k("Esc", 1.5), ..."1234567890".split("").map((c) => k(c)), k("-"), k("="), k("⌫", 1.5)],
  [k("Tab", 1.5), ..."QWERTYUIOP".split("").map((c) => k(c)), k("["), k("]"), k("\\", 1.5)],
  [k("Caps", 1.75), ..."ASDFGHJKL".split("").map((c) => k(c)), k(";"), k("'"), k("↵", 2.25)],
  [k("⇧", 2.25), ..."ZXCVBNM".split("").map((c) => k(c)), k(","), k("."), k("/"), k("⇧", 2.75)],
  [k("⌃", 1.25), k("⌥", 1.25), k("⌘", 1.5), k("Space", 5.5), k("⌘", 1.5), k("⌥", 1.25), k("←"), k("→"), k("↑"), k("↓")],
];

/** The names people write a key by, mapped to its legend on the board. */
const ALIASES: Readonly<Record<string, string>> = {
  cmd: "⌘",
  command: "⌘",
  meta: "⌘",
  mod: "⌘",
  "⌘": "⌘",
  ctrl: "⌃",
  control: "⌃",
  "⌃": "⌃",
  alt: "⌥",
  option: "⌥",
  opt: "⌥",
  "⌥": "⌥",
  shift: "⇧",
  "⇧": "⇧",
  enter: "↵",
  return: "↵",
  "↵": "↵",
  esc: "Esc",
  escape: "Esc",
  backspace: "⌫",
  delete: "⌫",
  "⌫": "⌫",
  tab: "Tab",
  space: "Space",
  left: "←",
  right: "→",
  up: "↑",
  down: "↓",
  "?": "/",
};

/** The board legend a shortcut's key lights, or null when the board has no such key. */
export function legendFor(key: string): string | null {
  const alias = ALIASES[key.toLowerCase()] ?? ALIASES[key];
  if (alias) return alias;
  const upper = key.toUpperCase();
  return BOARD.some((row) => row.some((c) => c.legend === upper)) ? upper : null;
}

/** Every board legend a shortcut lights. "?" needs Shift as well as its key. */
export function lit(keys: readonly string[]): Set<string> {
  const out = new Set<string>();
  for (const key of keys) {
    const legend = legendFor(key);
    if (legend) out.add(legend);
    if (key === "?") out.add("⇧");
  }
  return out;
}
